{"command":"python3 -c "
import zipfile, json, io

z = zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip')
def count(name):
    try:
        data = z.read(name).decode('utf-8-sig')
    except KeyError:
        return False, 0
    lines = [l for l in data.splitlines() if l.strip()]
    return True, max(len(lines)-1, 0)

summary = {}
for key, fname in [('stops','stops.txt'), ('routes','routes.txt'), ('trips','trips.txt'), ('stop_times','stop_times.txt')]:
    present, n = count(fname)
    summary[f'has_{key}'] = present
    summary[f'n_{key}'] = n

print(json.dumps(summary, indent=2))
with open('outputs/t04_gtfs_summary.json','w') as f:
    json.dump(summary, f, indent=2)
""}

